import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.DncwoWA8.js";const l="/projects/ai-skills/diagrams/install-selected-skills.svg",m=JSON.parse('{"title":"Install a reviewed skill selection","description":"","frontmatter":{"title":"Install a reviewed skill selection"},"headers":[],"relativePath":"workflows/install-selected-skills.md","filePath":"workflows/install-selected-skills.md"}'),o={name:"workflows/install-selected-skills.md"};function r(n,e,c,d,p,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="install-a-reviewed-skill-selection" tabindex="-1">Install a reviewed skill selection <a class="header-anchor" href="#install-a-reviewed-skill-selection" aria-label="Permalink to &quot;Install a reviewed skill selection&quot;">​</a></h1><p>This is a focused procedure. For its place in a larger workflow, see <a href="/projects/ai-skills/workflows/supporting-tools.html">Supporting tools and additional workflows</a>.</p><p>An existing project needs useful skills, not an automatic copy of the entire collection.</p><p><strong>Finish with:</strong> A verified installation of the approved skill selection, with project instructions unchanged.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+l+'" alt="Install a reviewed skill selection: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/install-selected-skills.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/install-selected-skills.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/install-selected-skills.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. No additional instruction requirement is recorded for these selected steps.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Choose categories and agents.</strong> <a href="/projects/ai-skills/guide/install.html"><code>sync-skills</code> CLI</a> performs this deterministic installation step.</li><li><strong>Preview selected commands.</strong> <a href="/projects/ai-skills/guide/install.html"><code>sync-skills</code> CLI</a> performs this deterministic installation step.</li><li><strong>Approve selected paths.</strong> <a href="/projects/ai-skills/guide/install.html"><code>sync-skills</code> CLI</a> owns this approval boundary; continue only when the applicable approval or existing approved setup is established.</li><li><strong>Install selected skills.</strong> <a href="/projects/ai-skills/guide/install.html"><code>sync-skills</code> CLI</a> performs this deterministic installation step.</li><li><strong>Verify files and notices.</strong> <a href="/projects/ai-skills/guide/install.html"><code>sync-skills</code> CLI</a> performs this deterministic installation step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Use the Node.js CLI for installation. Existing destinations require explicit overwrite approval; unsupported semantic adaptations stop installation. Instruction review is a separate, explicitly requested sync-my-agents operation, not an installation step.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/isolated-workspace.html"><code>isolated-workspace</code></a> when a modifying task needs a dedicated branch or bookmark and a choice between the current checkout and a separate workspace.</li><li>Choose <a href="/projects/ai-skills/skills/sync-my-agents.html"><code>sync-my-agents</code></a> when you explicitly want to review AGENTS.md and its referenced instruction documents.</li><li>Choose <a href="/projects/ai-skills/skills/instruction-maintenance.html"><code>instruction-maintenance</code></a> when instruction routing, dependencies, metadata, or policy documents appear missing, stale, conflicting, or unsuitable.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',17)])])}const k=s(o,[["render",r]]);export{m as __pageData,k as default};
